/**
 * Abbey edition represented by this public-safe contract.
 *
 * Mirrors the compile-time `edition::Edition` so a client is never told it is
 * talking to the safe edition when it is not. Neither variant grants extra
 * capabilities — [`CapabilitySet`] is identical in both.
 */
export type Edition =
  | "standard"
  | "personal";

/**
 * Commands accepted by the initial shared application service.
 */
export type AppCommand =
  | { type: "status" }
  | { type: "claims"; payload: ClaimsQuery }
  | { type: "read_routes"; payload: RouteAuditQuery }
  | { type: "submit_run"; payload: RunRequest }
  | { type: "get_run"; payload: RunQuery }
  | { type: "cancel_run"; payload: RunQuery }
  | { type: "run_events"; payload: RunEventsQuery };

/**
 * Events emitted by the presentation-neutral application service.
 */
export type AppEvent =
  | { type: "status"; payload: RuntimeStatus }
  | { type: "claims"; payload: ClaimsSnapshot }
  | { type: "route_audit"; payload: RouteAuditPage }
  | { type: "approval_requested"; payload: ApprovalRequest }
  | { type: "run_submitted"; payload: RunSubmission }
  | { type: "run_status"; payload: RunSnapshot }
  | { type: "cancellation_acknowledged"; payload: RunSnapshot }
  | { type: "run_events"; payload: RunEventPage };

/**
 * Runtime state exposed without process or user-state details.
 */
export type RuntimeState =
  | "ready";

/**
 * Safe, immutable process identity and supported application operations.
 */
export interface RuntimeStatus {
  protocol_version: number;
  schema_version: number;
  edition: Edition;
  state: RuntimeState;
  version: string;
  build_git: string;
  build_target: string;
  capabilities: CapabilitySet;
  /**
   * Startup-bound execution routes. Empty and omitted for protocol v1.
   */
  run_routes?: Array<RunRouteCapability>;
}

/**
 * Application operations granted by this edition.
 */
export type AppCapability =
  | "read_status"
  | "read_claims"
  | "read_run"
  | "read_run_events"
  | "submit_run"
  | "cancel_run"
  | "read_routes";

/**
 * Ordered, duplicate-free capability declaration.
 */
export interface CapabilitySet {
  capabilities: Array<AppCapability>;
}

/**
 * Canonical claim status, independent of terminal rendering labels.
 */
export type ClaimStatus =
  | "current"
  | "partial"
  | "proposed"
  | "blocked"
  | "out_of_scope"
  | "failed"
  | "revoked"
  | "superseded"
  | "expired";

/**
 * Bounded, typed query over the canonical claims table.
 */
export interface ClaimsQuery {
  status?: ClaimStatus | null;
  contains?: string | null;
}

export interface ClaimRecord {
  name: string;
  status: ClaimStatus;
  note: string;
  instead: string | null;
}

export interface ClaimsSnapshot {
  claims: Array<ClaimRecord>;
  matched: number;
}

/**
 * Sensitive operation class shown to a user before any future execution.
 */
export type ApprovalKind =
  | "file_system_mutation"
  | "network_access"
  | "process_execution"
  | "privilege_elevation";

/**
 * A presentation-neutral approval prompt. This type grants no authority.
 */
export interface ApprovalRequest {
  run_id: RunId;
  kind: ApprovalKind;
  summary: string;
}

// ---------------------------------------------------------------------------
// desktop/src-tauri/src/ipc.rs — desktop transport envelope
// ---------------------------------------------------------------------------

/**
 * Which transport served a desktop read.
 */
export type ConnectionSource =
  | "daemon"
  | "in_process";

/**
 * Where the daemon bearer was configured, by *kind* — never its value.
 */
export type BearerSource =
  | "inline_env"
  | "token_file"
  | "conflicting"
  | "installed_service";

/**
 * Non-secret description of how this desktop process reaches Abbey.
 */
export interface ConnectionInfo {
  source: ConnectionSource;
  /**
   * Daemon socket path, when a daemon is configured. Never a token.
   */
  socket_path: string | null;
  bearer_configured: boolean;
  bearer_source: BearerSource | null;
  /**
   * Human-readable explanation, safe to render and safe to log.
   */
  detail: string;
}

/**
 * Packaged identity of the running build, derived from `abbey::edition`.
 */
export interface BundleIdentity {
  edition: Edition;
  product_name: string;
  binary_name: string;
  daemon_binary_name: string;
  bundle_id: string;
  /**
   * Bundle identifier the running window was actually configured with.
   *
   * Equal to `bundle_id` in a correctly built app; the startup check in
   * `main.rs` refuses to run if they differ, so a personal build can never
   * present itself under the safe edition's identity.
   */
  configured_bundle_id: string;
}

/**
 * The state of one host-OS integration, as this app reports it.
 */
export type IntegrationState =
  | "not_registered"
  | "separate_process"
  | "daemon_owned";

/**
 * One host-OS integration fact.
 *
 * A state token the frontend can switch on, plus the sentence that explains
 * it. Every statement here is about *this* app, and none of them is a
 * promise that a future build will keep: the shipped build is the evidence.
 */
export interface IntegrationFact {
  state: IntegrationState;
  /**
   * One or two sentences. Safe to render and safe to log.
   */
  detail: string;
}

/**
 * What this desktop build does — and does not do — with the host OS.
 *
 * Every field is read-only and is derived from the build's own compiled-in
 * capability manifest and edition table. Nothing here registers a login item,
 * installs or starts a service, requests an OS permission, or spawns a
 * helper process; where such a fact cannot be read, it is reported as *not
 * registered* rather than guessed.
 */
export interface SystemIntegration {
  /**
   * The exact permission identifiers this build declares, in manifest order.
   */
  declared_permissions: Array<string>;
  /**
   * The declared permissions that could reach the filesystem, a shell, a
   * process, or the OS opener. Empty in the shipped build.
   */
  execution_capable_permissions: Array<string>;
  /**
   * Whether this app starts anything at login.
   */
  login_startup: IntegrationFact;
  /**
   * Whether this app installs or starts a background service.
   */
  background_service: IntegrationFact;
  /**
   * What closing this window does to daemon-owned work.
   */
  window_close: IntegrationFact;
}

/**
 * Category of an IPC failure. The frontend switches on this, so the strings
 * are part of the contract.
 */
export type IpcErrorKind =
  | "configuration"
  | "not_found"
  | "transport"
  | "protocol"
  | "rejected"
  | "unsupported_platform";

/**
 * A failure the frontend can render. Carries no secret material: every
 * message originates from an authored `Display` string in Abbey's daemon
 * error types, none of which interpolate bearer values.
 */
export interface IpcError {
  kind: IpcErrorKind;
  message: string;
  remedy: string | null;
}

// ---------------------------------------------------------------------------
// desktop/src-tauri/src/v3_ipc.rs — protocol-v3 memory/grant wire (codegen)
// ---------------------------------------------------------------------------

/**
 * Individually negotiated protocol-v3 authority. Declaration order is the
 * canonical serialized order.
 */
export type V3Capability =
  | "list_tools"
  | "invoke_tools"
  | "decide_tool_approvals"
  | "cancel_tools"
  | "read_memory"
  | "read_models"
  | "download_models"
  | "manage_models"
  | "read_training"
  | "manage_training"
  | "read_workers"
  | "cancel_jobs"
  | "read_claims_by_id"
  | "poll_events"
  | "infer_models";

/**
 * Ordered grant set. Wire shape matches `abbey::app_core::V3CapabilitySet`.
 */
export interface V3CapabilitySet {
  capabilities: Array<V3Capability>;
}

/**
 * Fixed-watermark page request.
 */
export interface V3PageQuery {
  after?: number;
  through?: number | null;
  limit?: number;
}

/**
 * Read-only query for one opaque resource identifier.
 */
export interface V3ResourceQuery {
  resource_id: string;
}

/**
 * Bounded search within one explicitly selected memory space.
 */
export interface V3SearchRequest {
  space_id: string;
  query: string;
  page: V3PageQuery;
}

/**
 * Sanitized state for a bounded operation.
 */
export type V3OperationState =
  | "available"
  | "queued"
  | "running"
  | "input_required"
  | "succeeded"
  | "failed"
  | "denied"
  | "cancelled"
  | "not_downloaded";

/**
 * Sanitized record used by inventory and metadata pages.
 */
export interface V3EntityRecord {
  id: string;
  label: string;
  state: V3OperationState;
}

/**
 * Fixed-watermark inventory page.
 */
export interface V3EntityPage {
  after: number;
  through: number;
  records: Array<V3EntityRecord>;
}

/**
 * Exact-identifier claim lookup result.
 *
 * Distinct from the protocol-v1 `ClaimsSnapshot`/`ClaimsQuery` pair that the
 * Claims view already renders: this is a single canonical record fetched by
 * stable ID through `ReadClaimsById`, not a filtered ledger page. `status`
 * reuses the `ClaimStatus` already projected from `src/app_core/contracts.rs`
 * rather than redeclaring it.
 */
export interface V3StableClaim {
  id: string;
  name: string;
  status: ClaimStatus;
  note: string;
}

/**
 * Declared effect of one protocol-v3 tool.
 *
 * Serde-identical to `abbey::app_core::V3ToolEffect`. The desktop renders the
 * daemon's own effect class; it never invents one, and it never turns an
 * advertised effect into an invitation to run the tool.
 */
export type V3ToolEffect =
  | "read_only"
  | "mutating"
  | "destructive";

/**
 * One advertised tool and its bounded JSON input schema.
 *
 * `input_schema` is the daemon's own advertised JSON Schema. The desktop
 * carries it verbatim and never interprets it: this client cannot call a tool,
 * so a schema is inventory, not an instruction.
 */
export interface V3ToolDescriptor {
  tool_id: string;
  description: string;
  effect: V3ToolEffect;
  input_schema: unknown;
}

/**
 * Fixed-watermark page of tool descriptors.
 */
export interface V3ToolPage {
  after: number;
  through: number;
  tools: Array<V3ToolDescriptor>;
}

/**
 * Exact immutable signed-model action, with single-use operation identity.
 */
export interface V3ModelAction {
  model_id: string;
  revision: string;
  operation_id: string;
}

export type V3ModelDevice =
  | "cpu"
  | "metal"
  | "cuda";

export interface V3ModelDetails {
  model_id: string;
  revision: string;
  architecture: string;
  configured_device: V3ModelDevice;
  license_sha256: string;
  license_accepted: boolean;
  loaded: boolean;
}

export interface V3OperationStatus {
  operation_id: string;
  resource_id: string;
  state: V3OperationState;
  progress_basis_points: number;
}

// ---------------------------------------------------------------------------
// src/effective_model.rs — effective model resolution
// ---------------------------------------------------------------------------

/**
 * Where an [`EffectiveModel`] answer came from.
 *
 * Two surfaces answer the same question from two different authorities, and
 * both are legitimate: the CLI and the TUI resolve from the *live local
 * configuration* (`cfg.backend` / `cfg.model`), while the desktop client
 * resolves from the *runtime's own published route* — the route the daemon
 * will actually run a turn on. This discriminator makes that difference
 * explicit so a consumer can never mistake one authority for the other, and
 * so a client can say which one it consulted.
 */
export type EffectiveModelSource =
  | "local-config"
  | "runtime-route";

/**
 * The model a turn would use right now, given the live backend and the live
 * model string.
 *
 * The backend is carried as its canonical label (`ollama`, `cursor-agent`,
 * `grok`, `fm`, `abi`, `claude`) rather than as the executor-selection
 * enum, so this contract crosses the crate boundary to the desktop client
 * without exposing the executor-selection internals. The backend parser is
 * the one place a label becomes a backend, so there is still exactly one
 * backend vocabulary.
 */
export interface EffectiveModel {
  /**
   * The canonical backend label a turn would use.
   */
  backend: string;
  /**
   * The live model string, trimmed. Empty means "unset".
   */
  raw: string;
  /**
   * The model id the backend would actually receive.
   */
  resolved: string;
  /**
   * Which authority this answer was resolved against.
   */
  source: EffectiveModelSource;
}
